(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.StudentExtras=factory();})(globalThis,function(){
 const themes=['crimson','midnight','pastel','neon'];
 function csvRows(text){const rows=[];let row=[],v='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(v);v='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(v);if(row.some(x=>x.trim()))rows.push(row);row=[];v='';}else v+=c;}if(quoted)throw Error('Unclosed quote in CSV.');row.push(v);if(row.some(x=>x.trim()))rows.push(row);return rows;}
 function parse(text){const rows=csvRows(text.replace(/^\uFEFF/,''));const header=rows.shift()?.map(x=>x.trim().toLowerCase());if(!header||!['day','start','end','subject'].every(k=>header.includes(k)))throw Error('CSV needs day,start,end,subject columns.');return rows.map((r,i)=>{const e=Object.fromEntries(header.map((k,j)=>[k,(r[j]||'').trim()]));const day=['monday','tuesday','wednesday','thursday','friday','saturday'].findIndex(d=>d===e.day.toLowerCase()||d.slice(0,3)===e.day.toLowerCase());if(day<0)throw Error('Invalid weekday on row '+(i+2));return {...e,day};});}
 const quote=s=>'"'+String(s??'').replace(/"/g,'""')+'"';
 const csv=rows=>['day,start,end,subject,faculty,room,type,batch',...rows.map(e=>[typeof e.day==='number'?['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][e.day]:e.day,e.start,e.end,e.subject,e.faculty,e.room,e.type||'lecture',e.batch||''].map(quote).join(','))].join('\n');
 function countdown(up,now){if(!up)return {label:'No upcoming classes',fraction:0};const start=new Date(up.date);start.setHours(...up.entry.start.split(':').map(Number),0,0);const end=new Date(start);end.setHours(...up.entry.end.split(':').map(Number),0,0);const current=now>=start&&now<end;const seconds=Math.max(0,Math.ceil(((current?end:start)-now)/1000));const mins=Math.ceil(seconds/60);return {label:current?'Happening now · '+mins+' min left':mins>=1440?'Next class in '+Math.floor(mins/1440)+'d '+Math.floor(mins%1440/60)+'h':'Your next class starts in '+(mins>=60?Math.floor(mins/60)+'h '+mins%60+'m':mins+' minute'+(mins===1?'':'s')),fraction:current?Math.max(0,Math.min(1,(now-start)/(end-start))):Math.max(0,1-seconds/3600),current};}
 return {themes,parse,csv,countdown};
});
